import type { CompanyId, InterviewCategory, InterviewQuestion } from "@/lib/types"
import { createStableIdFactory, idKey } from "@/lib/data/stable-id"

export const INTERVIEW_CATEGORIES: { id: InterviewCategory; label: string; icon: string }[] = [
  { id: "technical", label: "Technical", icon: "Cpu" },
  { id: "coding", label: "Coding", icon: "Code2" },
  { id: "domain", label: "Company / Domain", icon: "Building2" },
  { id: "hr", label: "HR", icon: "MessagesSquare" },
  { id: "managerial", label: "Managerial", icon: "Briefcase" },
]

const nextInterviewId = createStableIdFactory("iq")
export function iq(
  company: CompanyId,
  category: InterviewCategory,
  question: string,
  guidance: string,
  difficulty: InterviewQuestion["difficulty"],
  tags: string[],
  sourceId: string,
): InterviewQuestion {
  const id = nextInterviewId(idKey(company, category, question))
  return { id, company, category, question, guidance, difficulty, tags, sourceId }
}

